-- Generated by Supabase CLI migration new target_two_player_soccer_formations_v2.
-- Add eight selectable pieces per side and three formations. Preserve V1
-- receipts, the financial mechanism, all source/gacha history and retired G.
BEGIN;
SELECT pg_advisory_xact_lock(991101);
DO $guard$
BEGIN
  IF EXISTS(SELECT 1 FROM target_private.two_player_matches WHERE status IN ('waiting','playing')) THEN
    RAISE EXCEPTION 'Finish or cancel/refund all existing soccer rooms before the V2 protocol cutover' USING ERRCODE='23514'; END IF;
  IF (SELECT md5(prosrc) FROM pg_proc WHERE oid='public.two_player_rpc(text,text,jsonb)'::regprocedure)<>'2b503263ccaefdf6b31c9ec4fcc469ce' OR
    (SELECT md5(prosrc) FROM pg_proc WHERE oid='target_private.two_player_match_dto(uuid,boolean)'::regprocedure)<>'5955e15e31435f4606b3ff91fe7daf25' OR
    (SELECT md5(prosrc) FROM pg_proc WHERE oid='target_private.two_player_claim(uuid)'::regprocedure)<>'7103c7c16d42b167ce9d358087601894' OR
    (SELECT md5(prosrc) FROM pg_proc WHERE oid='target_private.two_player_settle(uuid,text,text,text)'::regprocedure)<>'3fda98dd6321745611b62b16030e975e' OR
    (SELECT md5(prosrc) FROM pg_proc WHERE oid='target_private.two_player_protect_move()'::regprocedure)<>'03a58cc0ab2db83c5df23a468389d24d' OR
    (SELECT md5(prosrc) FROM pg_proc WHERE oid='public.target_games_rpc(text,text,jsonb)'::regprocedure)<>'71ddbc56e79a79dcd8a046d556b73a59' THEN
    RAISE EXCEPTION 'Reviewed V1 soccer or retired gambling boundary changed'; END IF;
END $guard$;

CREATE FUNCTION target_private.two_player_initial_state(p_host integer,p_guest integer)
RETURNS jsonb LANGUAGE sql IMMUTABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
  WITH positions(formation,piece,x,y) AS(VALUES
    (0,0,320,900),(0,1,140,790),(0,2,320,790),(0,3,500,790),
    (0,4,140,670),(0,5,320,670),(0,6,500,670),(0,7,320,560),
    (1,0,320,900),(1,1,220,790),(1,2,420,790),(1,3,120,680),
    (1,4,320,680),(1,5,520,680),(1,6,230,560),(1,7,410,560),
    (2,0,320,900),(2,1,190,800),(2,2,450,800),(2,3,200,680),
    (2,4,440,680),(2,5,160,560),(2,6,320,560),(2,7,480,560))
  SELECT jsonb_build_object('players',jsonb_agg(jsonb_build_object('x',CASE WHEN seat=0 THEN x ELSE 640-x END,
    'y',CASE WHEN seat=0 THEN y ELSE 960-y END) ORDER BY seat,piece),'ball',jsonb_build_object('x',320,'y',480))
  FROM (VALUES(0),(1)) sides(seat) JOIN positions ON formation=CASE WHEN seat=0 THEN p_host ELSE p_guest END;
$$;
REVOKE ALL ON FUNCTION target_private.two_player_initial_state(integer,integer) FROM PUBLIC,anon,authenticated,service_role;

ALTER TABLE target_private.two_player_matches
  ADD COLUMN host_formation integer NOT NULL DEFAULT 0 CHECK(host_formation BETWEEN 0 AND 2),
  ADD COLUMN guest_formation integer NOT NULL DEFAULT 0 CHECK(guest_formation BETWEEN 0 AND 2),
  ADD COLUMN updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  ALTER COLUMN version SET DEFAULT 2,
  ALTER COLUMN state SET DEFAULT target_private.two_player_initial_state(0,0),
  DROP CONSTRAINT two_player_matches_version_check,
  ADD CONSTRAINT two_player_matches_version_check CHECK(version IN (1,2));
ALTER TABLE target_private.two_player_moves
  ADD COLUMN piece integer NOT NULL DEFAULT 0 CHECK(piece BETWEEN 0 AND 7),
  ALTER COLUMN charged_bytes SET DEFAULT 393216,
  DROP CONSTRAINT two_player_moves_version_check,
  ADD CONSTRAINT two_player_moves_version_check CHECK(version IN (1,2)),
  DROP CONSTRAINT two_player_moves_charged_bytes_check,
  ADD CONSTRAINT two_player_moves_charged_bytes_check CHECK(charged_bytes BETWEEN 1024 AND 393216),
  DROP CONSTRAINT two_player_moves_frames_check,
  ADD CONSTRAINT two_player_moves_frames_check CHECK(jsonb_typeof(frames)='array' AND pg_column_size(frames)<=360448);

CREATE FUNCTION target_private.two_player_match_updated()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
  NEW.updated_at:=greatest(clock_timestamp(),OLD.updated_at+interval '1 microsecond');
  RETURN NEW;
END $$;
CREATE TRIGGER two_player_match_updated BEFORE UPDATE ON target_private.two_player_matches
  FOR EACH ROW EXECUTE FUNCTION target_private.two_player_match_updated();
REVOKE ALL ON FUNCTION target_private.two_player_match_updated() FROM PUBLIC,anon,authenticated,service_role;

-- A queued old RPC body must not insert a V1 shot into a newly created V2 room.
CREATE FUNCTION target_private.two_player_move_version()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE m target_private.two_player_matches%rowtype;
BEGIN
  SELECT * INTO STRICT m FROM target_private.two_player_matches WHERE id=NEW.match_id;
  IF m.status<>'playing' OR m.version<>NEW.version OR m.round<>NEW.round OR m.turn<>NEW.actor THEN
    RAISE EXCEPTION 'Soccer move protocol is stale' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER two_player_move_version BEFORE INSERT ON target_private.two_player_moves
  FOR EACH ROW EXECUTE FUNCTION target_private.two_player_move_version();
REVOKE ALL ON FUNCTION target_private.two_player_move_version() FROM PUBLIC,anon,authenticated,service_role;

-- Checked textual adaptation retains the already reviewed financial branches.
-- This migration-only helper is removed before commit, exposing no new RPC.
CREATE FUNCTION target_private.two_player_v2_replace(p_source text,p_old text,p_new text,p_count integer DEFAULT 1)
RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
  IF (length(p_source)-length(replace(p_source,p_old,'')))/length(p_old)<>p_count THEN
    RAISE EXCEPTION 'Reviewed V2 adaptation marker mismatch: %',left(p_old,100); END IF;
  RETURN replace(p_source,p_old,p_new);
END $$;

DO $adapt$
DECLARE definition text;
BEGIN
  SELECT pg_get_functiondef('target_private.two_player_protect_move()'::regprocedure) INTO definition;
  definition:=target_private.two_player_v2_replace(definition,'NEW.actor,NEW.angle,NEW.power,NEW.created_at','NEW.actor,NEW.angle,NEW.power,NEW.piece,NEW.created_at');
  definition:=target_private.two_player_v2_replace(definition,'OLD.actor,OLD.angle,OLD.power,OLD.created_at','OLD.actor,OLD.angle,OLD.power,OLD.piece,OLD.created_at');
  EXECUTE definition;

  SELECT pg_get_functiondef('target_private.two_player_claim(uuid)'::regprocedure) INTO definition;
  definition:=target_private.two_player_v2_replace(definition,'''turn'',m.turn,''state'',m.state,',
    '''turn'',m.turn,''state'',m.state,''formations'',jsonb_build_array(m.host_formation,m.guest_formation),');
  definition:=target_private.two_player_v2_replace(definition,'''host'',jsonb_build_object(''angle'',CASE WHEN x.actor=''host''',
    '''host'',jsonb_build_object(''piece'',CASE WHEN x.actor=''host'' THEN x.piece ELSE 0 END,''angle'',CASE WHEN x.actor=''host''');
  definition:=target_private.two_player_v2_replace(definition,'''guest'',jsonb_build_object(''angle'',CASE WHEN x.actor=''guest''',
    '''guest'',jsonb_build_object(''piece'',CASE WHEN x.actor=''guest'' THEN x.piece ELSE 0 END,''angle'',CASE WHEN x.actor=''guest''');
  EXECUTE definition;

  SELECT pg_get_functiondef('target_private.two_player_match_dto(uuid,boolean)'::regprocedure) INTO definition;
  definition:=target_private.two_player_v2_replace(definition,'''createdAt'',m.created_at,''expiresAt''',
    '''createdAt'',m.created_at,''updatedAt'',m.updated_at,''expiresAt''');
  definition:=target_private.two_player_v2_replace(definition,'''offer'',m.host_offer,''ready''','''offer'',m.host_offer,''formation'',m.host_formation,''ready''');
  definition:=target_private.two_player_v2_replace(definition,'''offer'',m.guest_offer,''ready''','''offer'',m.guest_offer,''formation'',m.guest_formation,''ready''');
  definition:=target_private.two_player_v2_replace(definition,'''host'',jsonb_build_object(''angle'',CASE WHEN x.actor=''host''',
    '''host'',jsonb_build_object(''piece'',CASE WHEN x.actor=''host'' THEN x.piece ELSE 0 END,''angle'',CASE WHEN x.actor=''host''');
  definition:=target_private.two_player_v2_replace(definition,'''guest'',jsonb_build_object(''angle'',CASE WHEN x.actor=''guest''',
    '''guest'',jsonb_build_object(''piece'',CASE WHEN x.actor=''guest'' THEN x.piece ELSE 0 END,''angle'',CASE WHEN x.actor=''guest''');
  EXECUTE definition;

  SELECT pg_get_functiondef('target_private.two_player_settle(uuid,text,text,text)'::regprocedure) INTO definition;
  definition:=target_private.two_player_v2_replace(definition,
    'WITH released AS(UPDATE target_private.two_player_moves SET charged_bytes=1024,claim_token=NULL,claim_until=NULL'||chr(10)||
    '    WHERE match_id=p_id AND resolved_at IS NULL AND charged_bytes>1024 RETURNING 131072-1024 AS bytes)',
    'WITH pending AS(SELECT match_id,round,charged_bytes FROM target_private.two_player_moves'||chr(10)||
    '    WHERE match_id=p_id AND resolved_at IS NULL AND charged_bytes>1024 FOR UPDATE),'||chr(10)||
    '  released AS(UPDATE target_private.two_player_moves x SET charged_bytes=1024,claim_token=NULL,claim_until=NULL'||chr(10)||
    '    FROM pending WHERE x.match_id=pending.match_id AND x.round=pending.round RETURNING pending.charged_bytes-1024 AS bytes)');
  EXECUTE definition;

  SELECT pg_get_functiondef('public.two_player_rpc(text,text,jsonb)'::regprocedure) INTO definition;
  definition:=target_private.two_player_v2_replace(definition,'''offer'',''ready'',''state''','''offer'',''formation'',''ready'',''state''');
  definition:=target_private.two_player_v2_replace(definition,
    'is_mutation:=p_action IN (''create'',''join'',''offer'',''ready'',''input'',''resolve'',''cancel'');',
    'is_mutation:=p_action IN (''create'',''join'',''offer'',''formation'',''ready'',''input'',''resolve'',''cancel'');');
  definition:=target_private.two_player_v2_replace(definition,'''state'',''offer'',''ready''','''state'',''offer'',''formation'',''ready''',2);
  definition:=target_private.two_player_v2_replace(definition,
    'IF p_action=''ready'' THEN allowed_keys:=allowed_keys||ARRAY[''ready'']; END IF;',
    'IF p_action=''formation'' THEN allowed_keys:=allowed_keys||ARRAY[''formation'']; END IF;'||chr(10)||
    '  IF p_action=''ready'' THEN allowed_keys:=allowed_keys||ARRAY[''ready'']; END IF;');
  definition:=target_private.two_player_v2_replace(definition,'''round'',''version'',''angle'',''power''','''round'',''version'',''piece'',''angle'',''power''');
  definition:=target_private.two_player_v2_replace(definition,'p_input->''version'' IS DISTINCT FROM ''1''::jsonb','p_input->''version'' IS DISTINCT FROM ''2''::jsonb');
  definition:=target_private.two_player_v2_replace(definition,
    'IF p_action=''ready'' AND jsonb_typeof',
    'IF p_action=''formation'' AND (jsonb_typeof(p_input->''formation'') IS DISTINCT FROM ''number'' OR'||chr(10)||
    '    coalesce(p_input->>''formation'','''')!~''^[0-2]$'') THEN'||chr(10)||
    '    RETURN target_private.error_result(400,''INVALID_FORMATION'',''陣形を選び直してください。''); END IF;'||chr(10)||
    '  IF p_action=''ready'' AND jsonb_typeof');
  definition:=target_private.two_player_v2_replace(definition,
    'IF p_action=''input'' AND (jsonb_typeof(p_input->''angle'')',
    'IF p_action=''input'' AND (jsonb_typeof(p_input->''piece'') IS DISTINCT FROM ''number'' OR'||chr(10)||
    '    coalesce(p_input->>''piece'','''')!~''^[0-7]$'' OR jsonb_typeof(p_input->''angle'')');
  definition:=target_private.two_player_v2_replace(definition,'112640','360448');
  definition:=target_private.two_player_v2_replace(definition,'131072','393216',3);
  definition:=target_private.two_player_v2_replace(definition,
    'ELSIF p_action=''offer'' THEN',
    'ELSIF p_action=''formation'' THEN'||chr(10)||
    '      IF m.status<>''waiting'' THEN RETURN target_private.error_result(409,''MATCH_STARTED'',''開始済みの陣形は変更できません。''); END IF;'||chr(10)||
    '      UPDATE target_private.two_player_matches SET host_formation=CASE WHEN side=''host'' THEN (p_input->>''formation'')::integer ELSE host_formation END,'||chr(10)||
    '        guest_formation=CASE WHEN side=''guest'' THEN (p_input->>''formation'')::integer ELSE guest_formation END,'||chr(10)||
    '        state=target_private.two_player_initial_state(CASE WHEN side=''host'' THEN (p_input->>''formation'')::integer ELSE host_formation END,'||chr(10)||
    '          CASE WHEN side=''guest'' THEN (p_input->>''formation'')::integer ELSE guest_formation END),'||chr(10)||
    '        host_ready=false,guest_ready=false,expires_at=clock_timestamp()+interval ''10 minutes'' WHERE id=m.id RETURNING * INTO m;'||chr(10)||
    '    ELSIF p_action=''offer'' THEN');
  definition:=target_private.two_player_v2_replace(definition,
    'SET status=''playing'',stake=host_offer,escrow=2*host_offer,',
    'SET status=''playing'',stake=host_offer,escrow=2*host_offer,'||chr(10)||
    '          state=target_private.two_player_initial_state(host_formation,guest_formation),');
  definition:=target_private.two_player_v2_replace(definition,
    'IF x.actor<>side OR x.angle<>', 'IF x.actor<>side OR x.piece<>(p_input->>''piece'')::integer OR x.angle<>');
  definition:=target_private.two_player_v2_replace(definition,
    'two_player_moves(match_id,round,version,actor,angle,power)',
    'two_player_moves(match_id,round,version,actor,piece,angle,power)');
  definition:=target_private.two_player_v2_replace(definition,
    'VALUES(m.id,m.round,1,side,(p_input->>''angle'')::integer,(p_input->>''power'')::integer)',
    'VALUES(m.id,m.round,m.version,side,(p_input->>''piece'')::integer,(p_input->>''angle'')::integer,(p_input->>''power'')::integer)');
  definition:=target_private.two_player_v2_replace(definition,
    '''{"players":[{"x":320,"y":720},{"x":320,"y":240}],"ball":{"x":320,"y":480}}''::jsonb',
    'target_private.two_player_initial_state(m.host_formation,m.guest_formation)');
  EXECUTE definition;
END $adapt$;
DROP FUNCTION target_private.two_player_v2_replace(text,text,text,integer);
COMMENT ON FUNCTION public.two_player_rpc(text,text,jsonb) IS
  'Dedicated-credential alternating soccer V2: eight owned pieces per player, three pre-funded formations, shared wallet escrow and immutable server physics.';
COMMIT;
